/// <summary>
/// This method disable the update sales lines pop up
/// </summary>
public void write()
{
    SalesTable      salesTable          = this.cursor();
    CurrencyCode    targetCurrency      = salesTable.CurrencyCode;
    CurrencyCode    originalCurrency    = salesTable.orig().CurrencyCode;
    GUPParameters   gUPParameters       = GUPParameters::find();

    if(gUPParameters.METSuppressPriceUpdate)
    {
        salesTable.CurrencyCode = originalCurrency;
    }

    next write();

    if(gUPParameters.METSuppressPriceUpdate)
    {
        if (targetCurrency != originalCurrency)
        {
            ttsbegin;
            SalesTable salesTableUpdate = SalesTable::find(salesTable.SalesId, true);

            if (salesTableUpdate)
            {
                salesTableUpdate.CurrencyCode = targetCurrency;
                salesTableUpdate.doUpdate();

                SalesLine salesLine;
                while select forupdate salesLine
                    where salesLine.SalesId == salesTableUpdate.SalesId
                {
                    salesLine.CurrencyCode = targetCurrency;
                    salesLine.doUpdate();
                }
            }
            ttscommit;
        }
        this.research(true);
    }

}

/// <summary>
/// Restrict Sales Orders by user restricted warehouses
/// </summary>
public void init()
{
    next init();

    QueryBuildDataSource salesTableDS = this.query().dataSourceTable(tableNum(SalesTable));

    if (salesTableDS)
    {
        METSOROWarehouseRestrictionUserSecurityHelper::addWarehouseRestrictionRange(salesTableDS);
    }
}
